"use client";

/**
 * Drag-and-drop board; renders nothing unless the `kanban_board` flag is on.
 *
 * Must call (do not reimplement): isEnabled, can
 */
import { useState, useTransition } from "react";
import { EmptyState } from "@/components/ui/empty-state";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import type { MoveIssueInput } from "@/schemas/issue";
import type { ActionResult } from "@/types/api";
import type { IssueId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Issue, IssueBoardColumn, IssueStatus } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { moveIssueInColumns, orderColumns } from "./board-model";
import { KanbanColumn } from "./kanban-column";

export type KanbanBoardProps = {
  columns: readonly IssueBoardColumn[];
  actor: Actor;
  flags: FeatureFlagSnapshot;
  onMove: (input: MoveIssueInput) => Promise<ActionResult<Issue>>;
  /** Assignee lookup passed straight through to the cards. */
  users?: Readonly<Record<string, User>>;
};

export function KanbanBoard(props: KanbanBoardProps): ReactElement | null {
  const { columns, actor, flags, onMove, users } = props;

  // The snapshot the layout serialised is the fast path; `isEnabled()` is the
  // fallback for a snapshot that predates the flag.
  const boardEnabled =
    flags.kanban_board === true ||
    isEnabled("kanban_board", {
      orgId: actor.orgId,
      userId: actor.userId,
      plan: "free",
      role: actor.role,
    });

  const [local, setLocal] = useState<readonly IssueBoardColumn[] | null>(null);
  const [pending, startTransition] = useTransition();

  if (!boardEnabled) return null;

  const mayMove = can(actor, "issue:update", organizationResource(actor.orgId));
  const rendered = orderColumns(local ?? columns);

  if (rendered.every((column) => column.issues.length === 0)) {
    return (
      <EmptyState
        title="This board is empty"
        description="Create an issue to see it here."
      />
    );
  }

  function handleDrop(
    toStatus: IssueStatus,
    issueId: IssueId,
    toIndex: number,
  ): void {
    if (!mayMove) return;
    // Land the card immediately, then let the action reconcile; on failure the
    // local override is dropped and the server columns win again.
    const optimistic = moveIssueInColumns(rendered, issueId, toStatus, toIndex);
    setLocal(optimistic);

    startTransition(async () => {
      const result = await onMove({
        orgId: actor.orgId,
        issueId,
        toStatus,
        toIndex,
      });
      if (!result.ok) setLocal(null);
    });
  }

  return (
    <div
      className="kanban-board flex gap-3 overflow-x-auto"
      aria-busy={pending}
    >
      {rendered.map((column) => (
        <KanbanColumn
          key={column.status}
          column={column}
          actor={actor}
          onDrop={(issueId, toIndex) =>
            handleDrop(column.status, issueId, toIndex)
          }
          {...(users !== undefined ? { users } : {})}
        />
      ))}
    </div>
  );
}
/**
 * Pure board arithmetic: grouping issues into columns and computing what a
 * drop produces.
 *
 * The board is optimistic — the card has to land under the cursor before the
 * server action resolves — so the "what does the board look like after this
 * move?" question must be answerable synchronously and identically on both
 * sides. Keeping it here (rather than inside the drag handler) is what makes
 * that testable.
 */
import { BOARD_STATUS_ORDER } from "../issue/issue-tone";
import type { IssueId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueStatus } from "@/types/issue";

/** Sort inside a column: urgent work first, then oldest — the queue people
 *  actually want to see. */
const PRIORITY_WEIGHT: Readonly<Record<Issue["priority"], number>> = {
  urgent: 0,
  high: 1,
  medium: 2,
  low: 3,
  none: 4,
};

export function compareBoardIssues(a: Issue, b: Issue): number {
  const byPriority = PRIORITY_WEIGHT[a.priority] - PRIORITY_WEIGHT[b.priority];
  if (byPriority !== 0) return byPriority;
  return a.createdAt.localeCompare(b.createdAt);
}

/** Groups a flat issue list into one column per status, in workflow order. */
export function buildBoardColumns(
  issues: readonly Issue[],
): readonly IssueBoardColumn[] {
  const byStatus = new Map<IssueStatus, Issue[]>();
  for (const status of BOARD_STATUS_ORDER) byStatus.set(status, []);

  for (const issue of issues) {
    const bucket = byStatus.get(issue.status);
    if (bucket === undefined) continue;
    bucket.push(issue);
  }

  return BOARD_STATUS_ORDER.map((status) => {
    const bucket = (byStatus.get(status) ?? []).sort(compareBoardIssues);
    return { status, issues: bucket, total: bucket.length };
  });
}

/** Re-orders arbitrary columns into the canonical workflow order. */
export function orderColumns(
  columns: readonly IssueBoardColumn[],
): readonly IssueBoardColumn[] {
  return [...columns].sort(
    (a, b) =>
      BOARD_STATUS_ORDER.indexOf(a.status) -
      BOARD_STATUS_ORDER.indexOf(b.status),
  );
}

export function findIssue(
  columns: readonly IssueBoardColumn[],
  issueId: IssueId,
): Issue | null {
  for (const column of columns) {
    const found = column.issues.find((issue) => issue.id === issueId);
    if (found !== undefined) return found;
  }
  return null;
}

/**
 * Moves one issue to `toStatus` at `toIndex`, returning fresh columns.
 *
 * `toIndex` is clamped: dropping past the end of a column is a normal gesture,
 * not an error, and a drop onto the column the card already sits in is a
 * re-order rather than a status change.
 */
export function moveIssueInColumns(
  columns: readonly IssueBoardColumn[],
  issueId: IssueId,
  toStatus: IssueStatus,
  toIndex: number,
): readonly IssueBoardColumn[] {
  const moving = findIssue(columns, issueId);
  if (moving === null) return columns;

  const moved: Issue = { ...moving, status: toStatus };

  return columns.map((column) => {
    if (column.status === toStatus) {
      const without = column.issues.filter((issue) => issue.id !== issueId);
      const index = Math.max(0, Math.min(toIndex, without.length));
      const next = [
        ...without.slice(0, index),
        moved,
        ...without.slice(index),
      ];
      return { status: column.status, issues: next, total: next.length };
    }

    if (column.issues.some((issue) => issue.id === issueId)) {
      const next = column.issues.filter((issue) => issue.id !== issueId);
      return { status: column.status, issues: next, total: next.length };
    }

    return column;
  });
}
/**
 * Issue rows: the widest query surface in the app. Every method takes `orgId` first and honours `IssueFilter.includeArchived`.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived
 */
import {
  and,
  count,
  desc,
  eq,
  inArray,
  isNotNull,
  isNull,
  like,
  lt,
  or,
  sql,
} from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { attachments, comments, getDb, issueLabels, issues } from "@/server/db";
import { ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toIssue } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type {
  CreateIssueInput,
  IssueFilterInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type {
  ArchiveScope,
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  Page,
  ProjectId,
  UserId,
